CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'editor', active INTEGER NOT NULL DEFAULT 1, session_version INTEGER NOT NULL DEFAULT 1, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS pages (id VARCHAR(40) PRIMARY KEY, title VARCHAR(200) NOT NULL, eyebrow VARCHAR(160) NOT NULL, summary TEXT NOT NULL, body MEDIUMTEXT NOT NULL, image VARCHAR(500) NOT NULL DEFAULT '', seo VARCHAR(200) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL DEFAULT 'draft', updated_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS revisions (id INTEGER PRIMARY KEY AUTO_INCREMENT, page_id VARCHAR(40) NOT NULL, content MEDIUMTEXT NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200) NOT NULL, summary TEXT NOT NULL, body MEDIUMTEXT NOT NULL, image VARCHAR(500) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL DEFAULT 'draft', published_at VARCHAR(30) NULL, updated_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL, url VARCHAR(500) NOT NULL, type VARCHAR(100) NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS enquiries (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, organisation VARCHAR(190) NOT NULL, category VARCHAR(120) NOT NULL, message TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'new', created_at VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTO_INCREMENT, kind VARCHAR(20) NOT NULL, page VARCHAR(100) NOT NULL, sid VARCHAR(64) NOT NULL, source VARCHAR(190) NOT NULL, created_at VARCHAR(30) NOT NULL);
CREATE INDEX events_date ON events (created_at);
CREATE INDEX enquiries_status_date ON enquiries (status, created_at);
CREATE INDEX posts_status_date ON posts (status, published_at);
CREATE TABLE IF NOT EXISTS rate_limits (identity VARCHAR(64) PRIMARY KEY, hits INTEGER NOT NULL, expires_at BIGINT NOT NULL);
